import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import { listNotifications } from "@/server/services/notification-service";
import { createTenant, issueInput, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); });
afterAll(() => cleanup());

it("works", async () => {
  const t = await createTenant("scratch");
  const issue = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "x", assigneeId: t.userIds.admin } as never));
  const base = { orgId: t.org.id, issueId: issue.id, mentionedUserIds: [] };
  const top = await commentService.createComment(t.actors.owner, { ...base, body: "top @viewer @owner", parentId: null });
  expect(top.mentionedUserIds).toEqual([t.userIds.viewer]);
  const r1 = await commentService.createComment(t.actors.member, { ...base, body: "r1", parentId: top.id });
  const r2 = await commentService.createComment(t.actors.admin, { ...base, body: "r2 @member", parentId: r1.id });
  await commentService.deleteComment(t.actors.owner, { orgId: t.org.id, commentId: r1.id });
  const thread = await commentService.getThread(t.actors.owner, t.org.id, issue.id);
  console.log(JSON.stringify(thread.map(n => [n.comment.body, n.replies.map(r => [r.id === r1.id, r.body, r.archivedAt !== null])])));
  const edited = await commentService.updateComment(t.actors.admin, { orgId: t.org.id, commentId: r2.id, body: "r2 @member @owner" });
  expect(edited.mentionedUserIds).toEqual([t.userIds.member, t.userIds.owner]);
  for (const who of ["owner", "admin", "member", "viewer"] as const) {
    const page = await listNotifications(t.actors.owner, { orgId: t.org.id, recipientId: t.userIds[who], unreadOnly: false, limit: 50, cursor: null });
    console.log(who, page.items.map(i => i.kind));
  }
  let n = 0;
  for (; n < 200; n++) { try { await commentService.createComment(t.actors.member, { ...base, body: "spam", parentId: null }); } catch { break; } }
  console.log("member burst", n);
  await commentService.createComment(t.actors.admin, { ...base, body: "still ok", parentId: null });
});
EOF
npx vitest run tests/zz-scratch.test.ts 2>&1 | grep -v "npm warn" | head -40; rm tests/zz-scratch.test.ts

